I use a call to `wait_for_console()` in `main()`.  Something like this might be added to Zephyr as a helper function.

```
int
wait_for_console()
{
  struct device *cons = device_get_binding(console_label);
  int rc = 0;

  if (IS_ENABLED(CONFIG_USB)) {
    usb_enable(usb_dc_status);
  }

  if ((rc == 0) && IS_ENABLED(CONFIG_USB_UART_CONSOLE)) {
    uint32_t dtr;
    do {
      uart_line_ctrl_get(cons, UART_LINE_CTRL_DTR, &dtr);
    } while (!dtr);
  }

  printk("%s Up and running: %d\n", zxxpab::utils::now_str(), rc);

  return rc;
}
```
